using System;using System.Reflection;
class RenderCliTests {
 static void Main(string[] a){try{var t=Assembly.LoadFrom(a[0]).GetType("MySFformat.RenderCliOptions");if(t==null)throw new Exception("Missing synchronous render CLI");var p=t.GetMethod("Parse");var args=new[]{"--render","saber.flver","--screenshot","result.png","--width","800","--height","600"};var o=p.Invoke(null,new object[]{args});if((int)t.GetField("Width").GetValue(o)!=800)throw new Exception("Width not parsed");int n=2;foreach(var bad in new[]{new[]{"--render","saber.flver"},new[]{"--render","saber.flver","--screenshot","a.png","--width","0"},new[]{"--render","saber.flver","--screenshot","a.png","--typo"},new[]{"--render","saber.flver","--screenshot","a.jpg"}}){bool reject=false;try{p.Invoke(null,new object[]{bad});}catch(TargetInvocationException){reject=true;}if(!reject)throw new Exception("Expected invalid arguments to fail");n++;}Console.WriteLine("PASS render CLI assertions: "+n);}catch(Exception e){Console.WriteLine("FAIL: "+e.Message);Environment.Exit(1);}}
}
